arguments.query:
query {
      game(slug: "marvels-wolverine-2") {
        id name slug status subscriberCount videoCount productCount
        products(first: 20) { nodes { id title slug status } pageInfo { total hasMore } }
        content(first: 50, orderBy: "published_at", orderDir: "desc") { nodes { id type title slug status } pageInfo { total hasMore } }
        collections(first: 20) { nodes { id title slug visibility } pageInfo { total hasMore } }
        events(first: 20) { nodes { id type title status } pageInfo { total hasMore } }
        sourceStates(first: 20) { nodes { id sourceType sourceName status } pageInfo { total hasMore } }
      }
    }
